package com.erudit.notificator.service;import com.erudit.integration.*;import com.erudit.integration.InternalClients.AnalyticsClient;import com.erudit.integration.InternalContracts.AnalyticsEvent;import com.erudit.notificator.repository.DeliveryRepository;import io.github.resilience4j.circuitbreaker.CircuitBreakerRegistry;import java.time.*;import java.util.*;import lombok.RequiredArgsConstructor;import org.springframework.beans.factory.ObjectProvider;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor public class NotificationScheduler {private final DeliveryRepository repository;private final MockNotificationSender sender;private final ObjectProvider<AnalyticsClient> analytics;private final CircuitBreakerRegistry breakers;
 @Scheduled(cron="${erudit.notifications.trigger-cron:0 */5 * * * *}") public void deliver(){repository.pending(100).forEach(n->{var attempt=sender.send(n,OffsetDateTime.now(ZoneOffset.UTC));if("MOCK_DELIVERED".equals(attempt.status()))publish(n.userId(),n.id());});}
 private void publish(UUID user,UUID notification){AnalyticsClient client=analytics.getIfAvailable();if(client==null)return;ResilientExecutor.execute(breakers.circuitBreaker("internal"),()->{client.publish(new AnalyticsEvent(UUID.randomUUID(),user,"NOTIFICATION_MOCK_DELIVERED",OffsetDateTime.now(ZoneOffset.UTC),Map.of("notificationId",notification)));return true;},()->false);}
}
